WHERE NOT EXISTS (SELECT 1 FROM incoming_vital_ranges i WHERE i.code = r.code AND i.sex = r.sex AND i.from_months = r.from_months);
INSERT INTO ehr.vital_reference_ranges (code, sex, from_months, to_months, low, high, kind, source)
SELECT code, sex, from_months, to_months, low, high, kind, source FROM incoming_vital_ranges
ON CONFLICT (code, sex, from_months) DO UPDATE
    SET to_months = excluded.to_months, low = excluded.low, high = excluded.high, kind = excluded.kind, source = excluded.source;
